<template>
  <section v-loading="loading" class="return-document-detail">
    <el-alert v-if="sync.updating" title="入库单来源信息正在同步，完成后自动刷新；整单数量以同步完整后的结果为准。" type="info" :closable="false" show-icon />
    <el-alert v-if="sync.warning" :title="sync.warning" type="warning" :closable="false" />
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <div v-if="!detail&&!loading" class="toolbar"><el-button @click="load">重新加载入库单</el-button></div>
    <template v-if="detail">
      <header><div><h2>{{ sn }} <el-button v-clipboard:copy="sn" type="text" icon="el-icon-document-copy" title="复制实际入库单号" /></h2><p class="muted"><el-tag size="mini">{{ detail.source_count>1?'合包退货入库':'独立退货入库' }}</el-tag> {{ sourceText(detail) }} · {{ detail.source_count }} 项实际退回来源 · 创建 {{ detail.create_time }}</p></div><el-button size="small" icon="el-icon-refresh" :loading="loading" @click="load">刷新详情</el-button></header>
      <el-alert :title="nextStep(detail)" :type="detail.stage==='NEED_CHECK'?'warning':'info'" :closable="false" show-icon />
      <div class="stages"><article><span>仓库下发与受理</span><strong :class="warehouseTone(warehouse.warehouse_state)">{{ warehouseStates[warehouse.warehouse_state] || '受理状态待核对' }}</strong><div class="muted">{{ warehouse.external_order ? '仓库单号 '+warehouse.external_order : '尚无仓库受理号' }}</div></article><article><span>仓库实收</span><strong>{{ receiveLabel(detail) }}</strong><div class="muted">{{ detail.pending_count?'待归属部分尚未计入来源实收':'以仓库已确认并明确来源的实收为准' }}</div></article><article><span>库存入账</span><strong>{{ postingLabel(detail) }}</strong><div class="muted">只有确认入账的明细增加库存</div></article></div>
      <div class="metrics"><article v-for="m in metrics" :key="m.field"><span>{{ m.label }}</span><strong>{{ quantityText(detail.units,m.field) }}</strong></article></div>
      <div class="identity-grid"><div><span>接收虚仓 / 实仓 / 货主</span><b>{{ storeName }} / {{ detail.real_store_code || '实仓待核对' }} / {{ detail.owner_code || '货主待核对' }}</b></div><div><span>本次退回快递 / 运单</span><b>{{ detail.carrier || '承运商待确认' }} · {{ detail.waybill || '退回运单尚未提供' }}</b></div><div><span>关联退回包裹</span><b>{{ detail.parcel_sn || '独立安排，无共同包裹号' }}</b></div><div><span>当前仓库状态 / 信息核对时间</span><b>{{ warehouse.warehouse_status || '仓库尚未返回状态' }} · {{ detail.sync_time }}</b></div></div>
      <p class="scope">当前展示<strong>整张入库单</strong>，包含全部关联退款、换货及赠品。<span v-if="detail.matched_count">已高亮命中的售后来源，整单数量保持完整。</span>资金退款和换出发货在对应售后详情中跟踪。</p>
      <el-alert v-if="factsError" :title="factsError" type="warning" :closable="false" />
      <el-alert v-if="shortReceipt" title="仓库已回传最终收货，但未覆盖全部计划数量；请核对短收及待归属记录，不能作为普通待收货处理。" type="warning" :closable="false" />
      <el-tabs v-model="tab" class="document-tabs">
        <el-tab-pane label="入库明细" name="items">
          <p class="muted">按实际库存商品汇总；展开查看退款、换货、赠品及原实际发货来源。正品／次品以已确认实收明细为准。</p>
          <el-table :data="products" size="small" row-key="key" class="document-products">
            <el-table-column type="expand"><template slot-scope="{row}"><div class="expanded"><el-table :data="row.members" :row-class-name="memberClass" size="small"><el-table-column label="售后归属 / 平台子单" min-width="260"><template slot-scope="s"><router-link :to="sourceLink(s.row)">{{ s.row.owner_sn }}</router-link><el-tag v-if="s.row.matched" size="mini" type="success">命中来源</el-tag><div class="muted">{{ s.row.owner_kind==='REFUND'?'退款':'换货' }} · {{ s.row.platform_oid }}</div></template></el-table-column><el-table-column label="商品身份 / 所属销售商品" min-width="200"><template slot-scope="s"><el-tag size="mini" :type="s.row.is_gift?'warning':'info'">{{ s.row.is_gift?'赠品':'购买商品' }}</el-tag><div class="muted">{{ s.row.sales_parent || '独立库存商品' }}</div></template></el-table-column><el-table-column label="计划 / 实收 / 入账" min-width="160"><template slot-scope="s">{{ s.row.quantity }} / {{ s.row.accepted_quantity }} / {{ s.row.posted_quantity }} {{ s.row.unit }}</template></el-table-column><el-table-column label="原实际发货 / 成本" min-width="240"><template slot-scope="s">{{ s.row.original_shipment_sn || '来源待核对' }}<div class="muted">原去程运单 {{ s.row.outbound_waybills || '尚未提供' }}</div><div class="muted">原出库成本 ¥{{ (s.row.warehouse||{}).unit_cost }} / {{ s.row.unit }}</div></template></el-table-column></el-table></div></template></el-table-column>
            <el-table-column label="实际商品 / SKU / 规格" min-width="260"><template slot-scope="{row}"><strong>{{ row.goods_name || row.sku_sn }}</strong><div class="muted">{{ row.sku_sn }}</div><div class="muted">{{ row.members[0].spec_name || '规格未记录' }}</div><el-tag v-if="row.members.some(m=>m.is_gift)" size="mini" type="warning">{{ row.members.every(m=>m.is_gift)?'赠品':'含购买商品及赠品' }}</el-tag></template></el-table-column>
            <el-table-column label="计划退回" width="105"><template slot-scope="{row}">{{ row.quantity }} {{ row.unit }}</template></el-table-column>
            <el-table-column label="已确认实收" width="110"><template slot-scope="{row}">{{ row.accepted_quantity }} {{ row.unit }}</template></el-table-column>
            <el-table-column label="已入账 / 待入账" min-width="155"><template slot-scope="{row}"><b>{{ row.posted_quantity }} {{ row.unit }}</b><div :class="row.unposted?'warning':'muted'">待入账 {{ row.unposted }} {{ row.unit }}</div></template></el-table-column>
            <el-table-column label="正品 / 次品" min-width="120"><template slot-scope="{row}">{{ row.gradesKnown?row.good_qty+' / '+row.bad_qty:'明细尚未取得' }}</template></el-table-column>
            <el-table-column label="待收 / 已截停" min-width="130"><template slot-scope="{row}"><div>{{ row.difference?'差异待核对':'待收' }} {{ row.remaining }} {{ row.unit }}</div><div class="muted">已截停 {{ row.cancelled_quantity }} {{ row.unit }}</div></template></el-table-column>
            <el-table-column label="当前结果" min-width="150"><template slot-scope="{row}"><el-tag size="mini" :type="row.difference||row.unposted?'warning':row.posted_quantity>=row.quantity?'success':'info'">{{ row.difference?'最终实收差异待核对':row.unposted?'已收待入账':row.posted_quantity>=row.quantity?'实收与入账完成':row.cancelled_quantity?'剩余已截停':row.accepted_quantity?'部分实收':'待收货' }}</el-tag></template></el-table-column>
          </el-table>
        </el-tab-pane>
        <el-tab-pane label="售后归属" name="sources" lazy>
          <el-table :data="detail.members" :row-class-name="memberClass" size="small"><el-table-column label="来源售后 / 原业务订单" min-width="280"><template slot-scope="{row}"><el-tag size="mini">{{ row.owner_kind==='REFUND'?'退款':'换货' }}</el-tag><el-tag v-if="row.matched" size="mini" type="success">命中来源</el-tag><router-link :to="sourceLink(row)">{{ row.owner_sn }}</router-link><div><router-link :to="{path:'/oms-order/business',query:{orderId:row.order_id}}">{{ row.order_sn }}</router-link></div><div class="muted">平台主单 {{ row.platform_tid }}</div><div class="muted">平台子单 {{ row.platform_oid }}</div></template></el-table-column><el-table-column label="实际退回商品 / 身份" min-width="220"><template slot-scope="{row}">{{ row.goods_name }}<div class="muted">{{ row.sku_sn }}</div><el-tag size="mini" :type="row.is_gift?'warning':'info'">{{ row.is_gift?'赠品':'购买商品' }}</el-tag><div class="muted">{{ row.sales_parent }}</div></template></el-table-column><el-table-column label="计划 / 实收 / 入账" min-width="150"><template slot-scope="{row}">{{ row.quantity }} / {{ row.accepted_quantity }} / {{ row.posted_quantity }} {{ row.unit }}</template></el-table-column><el-table-column label="原实际发货 / 退回安排" min-width="230"><template slot-scope="{row}">{{ row.original_shipment_sn }}<div class="muted">去程 {{ row.outbound_waybills || '尚未提供' }}</div><div class="muted">第 {{ (row.warehouse||{}).generation }} 次安排</div><div class="muted">{{ (row.warehouse||{}).source_return_sn }}（来源成本记录）</div></template></el-table-column></el-table>
        </el-tab-pane>
        <el-tab-pane label="实收与库存" name="stock" lazy><return-receipt-ledger v-if="tab==='stock'" :sn="sn" section="RECEIPTS" :members="detail.members" @interaction="showInteraction" /><return-receipt-ledger v-if="tab==='stock'" :sn="sn" section="LINES" :members="detail.members" @interaction="showInteraction" /><return-receipt-ledger v-if="tab==='stock'" :sn="sn" section="REVIEWS" :members="detail.members" @interaction="showInteraction" /></el-tab-pane>
        <el-tab-pane label="仓库交互" name="interactions" lazy><return-interaction-panel v-if="tab==='interactions'" ref="interactions" :sn="sn" /></el-tab-pane>
      </el-tabs>
    </template>
  </section>
</template>
<script>
import { returnDetail, returnDocument } from '@/api/order/returns'
import { quantityText, sourceText, sourceLink, nextStep } from './returnManagementPresentation'
import { warehouseStates, warehouseTone, receiveLabel, postingLabel, productRows } from './returnDocumentPresentation'
import ReturnReceiptLedger from './ReturnReceiptLedger'
import ReturnInteractionPanel from './ReturnInteractionPanel'
export default {
  components: { ReturnReceiptLedger, ReturnInteractionPanel }, props: { sn: { type: String, required: true }, sourceNumber: { type: String, default: '' }, initialTab: { type: String, default: 'items' }, warehouses: { type: Array, default: () => [] } },
  data: () => ({ warehouseStates, detail: null, sources: [], loading: false, error: '', factsError: '', sequence: 0, timer: null, sync: {}, tab: 'items', metrics: [{ label: '整单计划', field: 'quantity' }, { label: '已确认实收', field: 'accepted_quantity' }, { label: '库存已入账', field: 'posted_quantity' }, { label: '实收待入账', field: 'unposted_quantity' }] }),
  computed: { storeName() { const code = this.detail.store_code; const w = this.warehouses.find(w => (w.code || w.wmsSimulationCode || w.wms_simulation_code) === code); return w ? (w.name || w.wmsSimulationName || w.wms_simulation_name || code) + '（'+code+'）' : code }, warehouse() { return (this.detail.warehouse_documents || [])[0] || {} }, products() { return productRows(this.detail.members, this.sources) }, shortReceipt() { return Number(this.warehouse.receipt_difference)>0 || this.sources.some(s => Number(s.final_confirmation) && Number(s.accepted_quantity) < Number(s.quantity) && s.cancel_state!=='CONFIRMED') } },
  watch: { sn: { immediate: true, handler() { this.tab = this.initialTab; this.load() } }, initialTab(value) { this.tab = value } }, beforeDestroy() { this.sequence++; clearTimeout(this.timer) },
  methods: {
    quantityText, sourceText, sourceLink, nextStep, warehouseTone, receiveLabel, postingLabel,
    memberClass({ row }) { return row.matched ? 'matched-source' : '' },
    async load() { clearTimeout(this.timer); const seq = ++this.sequence; this.loading = true; this.error = ''; this.factsError = ''; this.sources = []; try { const detail = (await returnDetail({ view: 'DOCUMENT', key: this.sn, number: this.sourceNumber, numberType: 'ANY' })).data; if (seq !== this.sequence) return; this.sync = detail.synchronization || {}; if (this.sync.updating && !this.sync.warning) this.timer = setTimeout(() => this.load(), 1500); if (detail.loading) { this.detail = null; if (!this.sync.updating) this.error = '入库单来源暂未同步完成，请稍后刷新重试'; return } this.detail = detail; try { const facts = (await returnDocument({ sn: this.sn })).data; if (seq === this.sequence) this.sources = facts.sources || [] } catch (_) { if (seq === this.sequence) this.factsError = '实收质量明细暂未取得，正次品不按0处理，请刷新详情重试' } } catch (_) { if (seq === this.sequence) { this.detail = null; this.error = '退货入库单详情加载失败或没有查看权限，请刷新后重试' } } finally { if (seq === this.sequence) this.loading = false } },
    async showInteraction(id) { this.tab = 'interactions'; await this.$nextTick(); if (this.$refs.interactions) this.$refs.interactions.show(id) }
  }
}
</script>
<style scoped>.return-document-detail{padding:4px 24px 40px;color:#34445b;min-height:220px}header,.toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}h2{font-size:18px;overflow-wrap:anywhere;margin:8px 0}.muted{font-size:12px;color:#7a899d;line-height:1.9;overflow-wrap:anywhere}.stages,.metrics{display:grid;gap:12px;margin:18px 0}.stages{grid-template-columns:repeat(3,1fr)}.metrics{grid-template-columns:repeat(4,1fr)}.stages article,.metrics article{padding:16px;border:1px solid #e3eaf3;border-radius:7px;background:#f6f9fd}.stages span,.metrics span,.identity-grid span{display:block;color:#7a899d;font-size:12px}.stages strong{display:block;font-size:15px;margin:9px 0}.metrics strong{display:block;font-size:23px;margin-top:10px}.identity-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;border:1px solid #e3eaf3;border-radius:7px;padding:18px}.identity-grid b{display:block;font-size:13px;font-weight:500;margin-top:7px;overflow-wrap:anywhere}.scope{padding:13px 16px;background:#f4f7fc;font-size:12px;line-height:1.9;color:#6c7e94}.document-tabs{margin-top:18px}.warning{color:#b77d19}.danger{color:#c74545}.success{color:#278558}.expanded{padding:4px 18px 15px}.el-tag{margin:3px 6px 3px 0}.return-document-detail ::v-deep td{vertical-align:top}.return-document-detail ::v-deep .matched-source td{background:#edf5ff!important}.return-document-detail ::v-deep .cell{overflow-wrap:anywhere}@media(max-width:900px){.return-document-detail{padding:4px 12px 30px}.stages,.metrics,.identity-grid{grid-template-columns:1fr 1fr}}
</style>
